/**
 * The cloud contract (ADR 0011, 0012): the documents the game, its Cloud
 * Functions and the admin area exchange (boards, attempts, commands, the
 * cloud records and the feature toggles), their ids, parsers and sorts,
 * all declared under `lib/state/cloud/`. Imported as
 * `@wolsok/feat-shared-bacteria-engine/cloud`; the main entry exports
 * none of it. A name enters it with its first consumer outside the engine.
 */
export {
  ADMIN_COMMAND_TYPES,
  BAN_REASONS,
  DESTRUCTIVE_COMMAND_TYPES,
  isUid,
  parseAdminCommand,
  REASON_MAX,
} from './lib/state/cloud/admin-commands';
export type {
  AdminCommand,
  AdminCommandType,
  BanReason,
  EntryTarget,
  PlayerTarget,
} from './lib/state/cloud/admin-commands';
export { ADMIN_STATS_FIGURES } from './lib/state/cloud/records/admin-stats';
export type {
  AdminStats,
  AdminStatsFigure,
} from './lib/state/cloud/records/admin-stats';
export {
  banHolds,
  mirroredBan,
  parseBan,
  parseMirroredBan,
} from './lib/state/cloud/records/ban';
export type { CloudBan } from './lib/state/cloud/records/ban';
export { HIDE_REASONS } from './lib/state/cloud/records/hide-reasons';
export type { HideReason } from './lib/state/cloud/records/hide-reasons';
export { NOTICE_TYPES } from './lib/state/cloud/records/notices';
export type { NoticeType } from './lib/state/cloud/records/notices';
export { REPLAY_KINDS, REPLAY_STATES } from './lib/state/cloud/records/replays';
export type {
  ReplayKind,
  ReplayState,
} from './lib/state/cloud/records/replays';
export {
  type StoredPlayback,
  storedPlaybackOf,
  storedPlaybackRefusal,
} from './lib/state/cloud/records/replay-playback';
export {
/**
 * @jest-environment node
 */
import { join, relative, sep } from 'node:path';
import * as ts from 'typescript';

const CLOUD_FOLDER = ['lib', 'state', 'cloud', ''].join(sep);

/** Where each name an entry exports is declared, relative to `src/`. */
function declaredFiles(entry: string): Map<string, string[]> {
  const file = join(__dirname, entry);
  const program = ts.createProgram([file], {
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    resolveJsonModule: true,
    skipLibCheck: true,
    noEmit: true,
  });
  const checker = program.getTypeChecker();
  const source = program.getSourceFile(file);
  const entrySymbol = source && checker.getSymbolAtLocation(source);
  if (!entrySymbol) {
    throw new Error(`${entry} has no exports`);
  }
  return new Map(
    checker.getExportsOfModule(entrySymbol).map((symbol) => {
      const target =
        symbol.flags & ts.SymbolFlags.Alias
          ? checker.getAliasedSymbol(symbol)
          : symbol;
      const files = (target.declarations ?? []).map((declaration) =>
        relative(__dirname, declaration.getSourceFile().fileName)
      );
      // An import that does not resolve leaves a name without declarations,
      // which would count as neither side and pass unchecked.
      if (files.length === 0) {
        throw new Error(`${entry}: ${symbol.name} has no declaration`);
      }
      return [symbol.name, files];
    })
  );
}

function namesDeclared(
  exports: Map<string, string[]>,
  where: (file: string) => boolean
): string[] {
  return [...exports]
    .filter(([, files]) => files.some(where))
    .map(([name]) => name);
}

const inCloud = (file: string) => file.startsWith(CLOUD_FOLDER);

describe('engine entries', () => {
  it('the main entry exports nothing of the cloud contract', () => {
    expect(namesDeclared(declaredFiles('index.ts'), inCloud)).toEqual([]);
  });

  it('the /cloud entry exports only the cloud contract', () => {
    const cloud = declaredFiles('cloud.ts');

    expect(cloud.size).toBeGreaterThan(0);
    expect(namesDeclared(cloud, (file) => !inCloud(file))).toEqual([]);
  });
});
