// node switch.cjs <root> <before.json>: moves GPU names of main-entry imports into /gpu imports.
const { createRequire } = require('module');
const path = require('path');
const fs = require('fs');
const root = path.resolve(process.argv[2]);
const ts = createRequire(path.join(root, 'package.json'))('typescript');
const before = require(path.resolve(process.argv[3])).entries[''];
const PKG = '@wolsok/feat-shared-bacteria-engine';
const isGpu = (n) => before[n] && /simulation\/(gpu-int\/|grid\/|grid-format)/.test(before[n].declared);
const files = new Set(Object.entries(before).filter(([n]) => isGpu(n)).flatMap(([, v]) => v.consumers));
for (const rel of files) {
  const file = path.join(root, rel);
  let text = fs.readFileSync(file, 'utf8');
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true);
  const edits = [];
  for (const st of sf.statements) {
    const isImp = ts.isImportDeclaration(st), isExp = ts.isExportDeclaration(st);
    if (!(isImp || isExp) || !st.moduleSpecifier || st.moduleSpecifier.text !== PKG) continue;
    const bindings = isImp ? st.importClause?.namedBindings : st.exportClause;
    if (!bindings || !bindings.elements) continue;
    const els = [...bindings.elements];
    const gpu = els.filter((e) => isGpu((e.propertyName || e.name).text));
    if (!gpu.length) continue;
    const rest = els.filter((e) => !gpu.includes(e));
    const typeOnly = isImp ? st.importClause.isTypeOnly : st.isTypeOnly;
    const kw = (isImp ? 'import' : 'export') + (typeOnly ? ' type' : '');
    const decl = (list, spec) => `${kw} { ${list.map((e) => e.getText()).join(', ')} } from '${spec}';`;
    const replacement = rest.length ? decl(rest, PKG) + '\n' + decl(gpu, PKG + '/gpu') : decl(gpu, PKG + '/gpu');
    edits.push([st.getStart(), st.getEnd(), replacement]);
  }
  for (const [s, e, r] of edits.sort((a, b) => b[0] - a[0])) text = text.slice(0, s) + r + text.slice(e);
  fs.writeFileSync(file, text);
  console.log(rel, edits.length);
}
EOF
